import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.I6s8z2kk.js";const g=JSON.parse('{"title":"Keeping these docs current","description":"","frontmatter":{},"headers":[],"relativePath":"dev/conventions/documentation.md","filePath":"dev/conventions/documentation.md"}'),d={name:"dev/conventions/documentation.md"};function n(i,e,r,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="keeping-these-docs-current" tabindex="-1">Keeping these docs current <a class="header-anchor" href="#keeping-these-docs-current" aria-label="Permalink to &quot;Keeping these docs current&quot;">​</a></h1><p>These guides live in <code>docs-site/</code> and are built with <a href="https://vitepress.dev" target="_blank" rel="noreferrer">VitePress</a>. They describe how the platform <strong>behaves today</strong>. Do not document planned features.</p><h2 id="the-rule" tabindex="-1">The rule <a class="header-anchor" href="#the-rule" aria-label="Permalink to &quot;The rule&quot;">​</a></h2><p>A change to business behaviour is not done until the docs match. In the same change:</p><ol><li>Update the matching <strong>developer page</strong> in <code>docs-site/dev/domain/&lt;module&gt;.md</code>.</li><li>If admins, center users or clients can see the change, update the matching <strong>user page</strong> in <code>docs-site/user/**</code>.</li><li>Look for <strong>stale</strong> statements, not only missing ones. Search the docs for the old behaviour.</li><li>Rebuild and commit the output: <code>npm run docs:build</code> (writes <code>storage/app/docs</code>).</li></ol><p>What counts as business behaviour: status rules, pricing and fees, permissions, validation and limits, new or changed endpoints and response fields, scheduled commands, and settings.</p><h2 id="adding-a-page" tabindex="-1">Adding a page <a class="header-anchor" href="#adding-a-page" aria-label="Permalink to &quot;Adding a page&quot;">​</a></h2><ol><li>Create the Markdown file under <code>docs-site/dev/...</code> or <code>docs-site/user/...</code>.</li><li>Register it in <code>docs-site/.vitepress/config.mts</code> (<code>devGroups</code> or <code>userGroups</code>), otherwise it has no sidebar entry.</li><li>Link to it from related pages.</li></ol><h2 id="writing-style" tabindex="-1">Writing style <a class="header-anchor" href="#writing-style" aria-label="Permalink to &quot;Writing style&quot;">​</a></h2><ul><li>Plain English, short sentences, tables for field lists and states.</li><li>Developer pages explain rules and name the classes involved. User pages describe what a person sees and does, without class names.</li><li>Amounts in halalas for developers; SAR for users.</li></ul><h2 id="where-things-are-served" tabindex="-1">Where things are served <a class="header-anchor" href="#where-things-are-served" aria-label="Permalink to &quot;Where things are served&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Content</th></tr></thead><tbody><tr><td><code>/guide</code></td><td>These guides (built output in <code>storage/app/docs</code>)</td></tr><tr><td><code>/docs</code></td><td>Endpoint reference generated by Scribe</td></tr></tbody></table><p>Both need a system user with <code>api_docs.view</code>.</p><h2 id="adding-a-language" tabindex="-1">Adding a language <a class="header-anchor" href="#adding-a-language" aria-label="Permalink to &quot;Adding a language&quot;">​</a></h2><p>The site is English only. To add Arabic, mirror the tree under <code>docs-site/ar/</code>, add a <code>locales</code> block to <code>config.mts</code> with <code>dir: &#39;rtl&#39;</code>, and extend this rule to require both languages.</p>',15)])])}const p=t(d,[["render",n]]);export{g as __pageData,p as default};
